#include <bits/stdc++.h>
#define MOD 1000000007LL

using namespace std;

struct V {
  long long arr[30];
};

struct M {
  long long mat[30][30];
};

long long totalCount, baseVal;

int getVal(long long num) {
  if (num < baseVal) return num;
  return (num + getVal(num / baseVal)) % baseVal;
}

M matrices[30], inv_matrices[30];
M E[200][40], EI[200][40];
V current_vector;

M multiply(M a, M b) {
  M res;
  for (int i = 0; i < baseVal; i++) {
    for (int j = 0; j < baseVal; j++) {
      res.mat[i][j] = 0;
      for (int l = 0; l < baseVal; l++) {
        res.mat[i][j] += (a.mat[i][l] * b.mat[l][j]) % MOD;
      }
      res.mat[i][j] %= MOD;
    }
  }
  return res;
}

V multiply(M m, V v) {
  V res;
  for (int i = 0; i < baseVal; i++) {
    res.arr[i] = 0;
    for (int j = 0; j < baseVal; j++) {
      res.arr[i] += (v.arr[j] * m.mat[i][j]) % MOD;
    }
    res.arr[i] %= MOD;
  }
  return res;
}

void precompute_matrices() {
  for (int i = 0; i < baseVal; i++) {
    E[0][i] = matrices[i];
    EI[0][i] = inv_matrices[i];
  }
  int LOG = 0;
  long long t = totalCount;
  while (t > 0) {
    LOG++;
    t /= baseVal;
  }
  for (int j = 1; j <= LOG; j++) {
    E[j][0] = E[j - 1][0];
    EI[j][0] = EI[j - 1][0];
    for (int l = 1; l < baseVal; l++) {
      E[j][0] = multiply(E[j - 1][l], E[j][0]);
      EI[j][0] = multiply(EI[j][0], EI[j - 1][l]);
    }
    for (int i = 1; i < baseVal; i++) {
      E[j][i] = multiply(E[j - 1][i - 1], multiply(E[j][i - 1], EI[j - 1][i - 1]));
      EI[j][i] = multiply(E[j - 1][i - 1], multiply(EI[j][i - 1], EI[j - 1][i - 1]));
    }
  }
}

V solve_vector(long long n, V v, int at) {
  if (n == 0) return v;
  int w = getVal(n / baseVal);
  v = solve_vector(n / baseVal, v, at + 1);
  for (int i = 0; i < n % baseVal; i++) {
    v = multiply(E[at][(w + i) % baseVal], v);
  }
  return v;
}

int main() {
  scanf("%lld %lld", &totalCount, &baseVal);
  for (int i = 0; i < baseVal; i++) {
    current_vector.arr[i] = 1;
    for (int j = 0; j < baseVal; j++) {
      for (int l = 0; l < baseVal; l++) {
        if (j == l) {
          matrices[i].mat[j][l] = 1;
          inv_matrices[i].mat[j][l] = 1;
        } else if (j == i) {
          matrices[i].mat[j][l] = 1;
          inv_matrices[i].mat[j][l] = -1;
        } else {
          matrices[i].mat[j][l] = 0;
          inv_matrices[i].mat[j][l] = 0;
        }
      }
    }
  }
  precompute_matrices();
  current_vector = solve_vector(totalCount, current_vector, 0);
  long long total_sum = 0;
  for (int i = 0; i < baseVal; i++) {
    total_sum += current_vector.arr[i];
  }
  total_sum--;
  total_sum %= MOD;
  if (total_sum < 0) total_sum += MOD;
  while (total_sum % (baseVal - 1) != 0) {
    total_sum += MOD;
  }
  printf("%lld\n", total_sum / (baseVal - 1));
}
